package com.ecoriego.app.ui;
import android.os.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.ecoriego.app.R;import com.ecoriego.app.data.DBHelper;import com.ecoriego.app.model.Planta;import java.text.*;import java.util.*;
public class PlantaFormActivity extends AppCompatActivity{DBHelper db;Planta edit;EditText n,e,freq,fecha,notas;Spinner sp;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_planta_form);db=new DBHelper(this);n=findViewById(R.id.etNombre);e=findViewById(R.id.etEspecie);fecha=findViewById(R.id.etFecha);freq=findViewById(R.id.etFrecuencia);notas=findViewById(R.id.etNotas);sp=findViewById(R.id.spUbicacion);ArrayAdapter<String>a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Interior","Exterior","Balcón","Jardín"});sp.setAdapter(a);int id=getIntent().getIntExtra("id",-1);if(id>0){edit=db.obtenerPlanta(id);findViewById(R.id.tvFormTitle).setVisibility(android.view.View.VISIBLE);n.setText(edit.getNombre());e.setText(edit.getEspecie());fecha.setText(edit.getFechaSiembra());freq.setText(String.valueOf(edit.getFrecuencia()));notas.setText(edit.getNotas());sp.setSelection(a.getPosition(edit.getUbicacion()));findViewById(R.id.tvFormTitle).setTag("edit");}else{fecha.setText(new SimpleDateFormat("yyyy-MM-dd",Locale.getDefault()).format(new Date()));freq.setText("3");}findViewById(R.id.btnGuardar).setOnClickListener(v->guardar());}void guardar(){String sn=n.getText().toString().trim(),se=e.getText().toString().trim(),sf=fecha.getText().toString().trim(),sfr=freq.getText().toString().trim();if(sn.isEmpty()||se.isEmpty()||sf.isEmpty()||sfr.isEmpty()){Toast.makeText(this,"Completa los campos obligatorios.",Toast.LENGTH_SHORT).show();return;}try{int fr=Integer.parseInt(sfr);if(fr<1||fr>365)throw new Exception();Planta p=new Planta(edit==null?0:edit.getId(),sn,se,sf,fr,sp.getSelectedItem().toString(),notas.getText().toString().trim());if(edit==null)db.insertarPlanta(p);else db.actualizarPlanta(p);Toast.makeText(this,"Planta guardada correctamente.",Toast.LENGTH_SHORT).show();finish();}catch(Exception ex){Toast.makeText(this,"La frecuencia debe ser un número entre 1 y 365.",Toast.LENGTH_SHORT).show();}}
}
